import {WebSocket} from 'ws';
import type {SessionEntry} from '../../types/session.js';
import type {OutgoingMessage} from '../../types/messages.js';

export function sendJson(ws: WebSocket, message: OutgoingMessage): void {
  ws.send(JSON.stringify(message));
}

export function sendUpsert(ws: WebSocket, index: number, entry: SessionEntry): void {
  sendJson(ws, {type: 'entry_upsert', index, entry});
}

export function sendDelta(ws: WebSocket, index: number, delta: string): void {
  sendJson(ws, {type: 'entry_delta', index, delta});
}

export function sendCommit(ws: WebSocket, index: number): void {
  sendJson(ws, {type: 'entry_commit', index});
}

export function sendError(ws: WebSocket, code: string, message: string): void {
  sendJson(ws, {type: 'error', code, message});
}

export function sendSkip(ws: WebSocket, index: number): void {
  sendJson(ws, {type: 'entry_skip', index});
}

export function sendStreamEnd(ws: WebSocket): void {
  sendJson(ws, {type: 'stream_end'});
}

## Over the WebSocket protocol

- A client sends `{type: 'list_sessions', limit?, before?}` and receives `{type: 'session_list', sessions}` for the socket's authenticated user, with `createdAt` and `updatedAt` serialised as ISO-8601 strings and any client-supplied `userId` ignored ([validated by: answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId](../../src/transport/conversationList.acceptance.test.ts#L93), [validated by: answers list_sessions with the authenticated session user and forwarded options](../../src/transport/ws/messageHandler.test.ts#L72)).
- A store without `listFor` answers `{type: 'session_list', sessions: []}`, and a throwing `listFor` logs an error on the `ws` category and answers `{type: 'error', code: 'SERVER_ERROR'}` ([validated by: answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws](../../src/transport/conversationList.acceptance.test.ts#L134)).
- The validator accepts an optional non-negative integer `limit` and an optional `before` cursor whose `sessionId` is 1–128 characters and whose `updatedAt` parses as a valid timestamp, rejecting any other `list_sessions` payload with `INVALID_MESSAGE` without calling `listFor` ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../src/transport/conversationList.acceptance.test.ts#L163)).
